import { ApiError, type DashboardApi } from './api.ts';
import { demoData, type DemoAlert } from './demoData.ts';
import type { Alert, AlertDetail, AlertFilters, Camera, CameraFeed, CameraZone, Store } from './types';

// Public demo: answers the dashboard's calls from static data and files in
// public/demo-dashboard/, generated by ai/tools/build_frontend_demo.py from
// store_test_01's manifest and this project's own footage. No network
// client, owner identity, token or camera address; every call is read-only.
export const demoStore: Store = {
  id: 'public-demo-store', name: 'Liquor Store', code: 'public-demo',
  timezone: 'Asia/Ho_Chi_Minh', role: 'operator',
};

// Alert times are kept relative to when the page was opened, so the demo
// always reads as a store being watched right now.
const openedAt = Date.now();

function requireDemoStore(storeId: string) {
  if (storeId !== demoStore.id) throw new ApiError('Store not available in the public demo.', 404);
}

const cameras: Camera[] = demoData.cameras.map((camera) => ({
  id: camera.id, storeId: camera.storeId, name: camera.name, cameraType: camera.cameraType,
  sourceType: camera.sourceType, isActive: camera.isActive, pipelines: [...camera.pipelines],
}));

function toAlert(item: DemoAlert): Alert {
  const camera = cameras.find((entry) => entry.id === item.cameraId);
  const detectedAt = new Date(openedAt - item.minutesAgo * 60_000).toISOString();
  const reviewed = item.status === 'confirmed' || item.status === 'acknowledged';
  return {
    id: item.id, storeId: demoStore.id, cameraId: item.cameraId, cameraName: camera?.name ?? null,
    pipelineType: item.pipelineType, eventType: item.eventType, severity: item.severity, status: item.status,
    detectedAt, closedAt: null, identityPersonId: null, identityLabel: item.identityLabel,
    identityScore: item.identityScore, reasonCodes: [...item.reasonCodes], metadata: { demo: true },
    reviewedById: null, reviewedByName: item.reviewedByName,
    reviewedAt: reviewed ? new Date(openedAt - Math.max(0, item.minutesAgo - 3) * 60_000).toISOString() : null,
    reviewNote: item.reviewNote, hasVideoEvidence: true, hasSnapshot: true,
  };
}

function alerts() {
  return demoData.alerts.map(toAlert).sort((a, b) => b.detectedAt.localeCompare(a.detectedAt));
}

function findAlert(alertId: string) {
  const item = demoData.alerts.find((entry) => entry.id === alertId);
  if (!item) throw new ApiError('This alert requires an owner sign-in or is not part of the demo.', 404);
  return item;
}

export const demoApi: DashboardApi = {
  readOnly: true,
  async getCameras(storeId) {
    requireDemoStore(storeId);
    return structuredClone(cameras);
  },
  async getZones(storeId, cameraId): Promise<CameraZone[]> {
    requireDemoStore(storeId);
    return structuredClone(demoData.zones[cameraId] ?? []);
  },
  async getAlerts(storeId, filters: AlertFilters = {}) {
    requireDemoStore(storeId);
    const items = alerts().filter((alert) => (
      (!filters.status || alert.status === filters.status)
      && (!filters.severity || alert.severity === filters.severity)
      && (!filters.eventType || alert.eventType === filters.eventType)
      && (!filters.pipelineType || alert.pipelineType === filters.pipelineType)
      && (!filters.cameraId || alert.cameraId === filters.cameraId)
    ));
    const start = filters.cursor ? Math.max(0, items.findIndex((item) => item.id === filters.cursor) + 1) : 0;
    const limit = Math.max(1, Math.min(100, filters.limit ?? 30));
    const page = items.slice(start, start + limit);
    return { items: page, nextCursor: start + limit < items.length ? page.at(-1)!.id : null };
  },
  async getAlert(storeId, alertId): Promise<AlertDetail> {
    requireDemoStore(storeId);
    const item = findAlert(alertId);
    const alert = toAlert(item);
    const started = new Date(new Date(alert.detectedAt).getTime() - (item.clipSeconds / 2) * 1000).toISOString();
    return {
      ...alert,
      media: [
        { id: `${item.id}:clip`, kind: 'clip', mimeType: 'video/mp4', startedAt: started, endedAt: null, durationSeconds: item.clipSeconds },
        { id: `${item.id}:snapshot`, kind: 'snapshot', mimeType: 'image/jpeg', startedAt: alert.detectedAt, endedAt: null, durationSeconds: null },
      ],
    };
  },
  async getMediaPlaybackUrl(storeId, alertId, mediaId) {
    requireDemoStore(storeId);
    const item = findAlert(alertId);
    if (mediaId === `${item.id}:clip`) return { url: item.clipUrl, expiresInSeconds: 3600 };
    if (mediaId === `${item.id}:snapshot`) return { url: item.snapshotUrl, expiresInSeconds: 3600 };
    throw new ApiError('Media is not part of the demo.', 404);
  },
  async actionAlert() {
    throw new ApiError('The public demo is read-only. Sign in to manage real alerts.', 403);
  },
  async getCameraFeed(storeId, cameraId): Promise<CameraFeed | null> {
    requireDemoStore(storeId);
    const camera = demoData.cameras.find((entry) => entry.id === cameraId);
    return camera ? { ...camera.feed, isRecording: true } : null;
  },
};
